insert into pb_ai.eval_runs(run, fn, label, k, ids, cases)
with s(i, code, name, wh) as (values (0,'AL','Alabama','Birmingham, AL'),(1,'AK','Alaska','Anchorage, AK'),(2,'AZ','Arizona','Tucson, AZ'),(3,'AR','Arkansas','Fayetteville, AR'),(4,'CA','California','Fresno, CA'),(5,'CO','Colorado','Colorado Springs, CO'),(6,'CT','Connecticut','Hartford, CT'),(7,'DE','Delaware','Dover, DE'),(8,'DC','District of Columbia','Washington, DC'),(9,'FL','Florida','Tampa, FL'),(10,'GA','Georgia','Savannah, GA'),(11,'HI','Hawaii','Honolulu, HI'),(12,'ID','Idaho','Boise, ID'),(13,'IL','Illinois','Springfield, IL'),(14,'IN','Indiana','Indianapolis, IN'),(15,'IA','Iowa','Des Moines, IA'),(16,'KS','Kansas','Wichita, KS'),(17,'KY','Kentucky','Lexington, KY'),(18,'LA','Louisiana','Baton Rouge, LA'),(19,'ME','Maine','Portland, ME'),(20,'MD','Maryland','Baltimore, MD'),(21,'MA','Massachusetts','Worcester, MA'),(22,'MI','Michigan','Grand Rapids, MI'),(23,'MN','Minnesota','Rochester, MN'),(24,'MS','Mississippi','Jackson, MS'),(25,'MO','Missouri','Kansas City, MO'),(26,'MT','Montana','Billings, MT'),(27,'NE','Nebraska','Omaha, NE'),(28,'NV','Nevada','Reno, NV'),(29,'NH','New Hampshire','Manchester, NH'),(30,'NJ','New Jersey','Newark, NJ'),(31,'NM','New Mexico','Albuquerque, NM'),(32,'NY','New York','Buffalo, NY'),(33,'NC','North Carolina','Raleigh, NC'),(34,'ND','North Dakota','Fargo, ND'),(35,'OH','Ohio','Cleveland, OH'),(36,'OK','Oklahoma','Tulsa, OK'),(37,'OR','Oregon','Salem, OR'),(38,'PA','Pennsylvania','Pittsburgh, PA'),(39,'RI','Rhode Island','Providence, RI'),(40,'SC','South Carolina','Columbia, SC'),(41,'SD','South Dakota','Sioux Falls, SD'),(42,'TN','Tennessee','Nashville, TN'),(43,'TX','Texas','San Antonio, TX'),(44,'UT','Utah','Provo, UT'),(45,'VT','Vermont','Burlington, VT'),(46,'VA','Virginia','Richmond, VA'),(47,'WA','Washington','Spokane, WA'),(48,'WV','West Virginia','Charleston, WV'),(49,'WI','Wisconsin','Madison, WI'),(50,'WY','Wyoming','Cheyenne, WY')),
c as (select i*2 n, jsonb_build_object('id','cs-'||lower(code)||'-fed','q','Does '||name||' follow the federal confined space rule, or does it have its own?','where',wh,'level','foreman') j from s
 union all select i*2+1, jsonb_build_object('id','cs-'||lower(code)||'-co','q','What is the carbon monoxide limit for entering a manhole?','where',wh,'level','pipelayer') from s
 union all select 1000+o, e from jsonb_array_elements('[{"id": "cs-ca-rescue", "q": "Can we rely on the fire department for rescue on a manhole entry, or do we need someone at the site?", "where": "Fresno, CA", "level": "foreman"}, {"id": "cs-ca-order", "q": "What order do we test the air in a vault before entry?", "where": "Fresno, CA", "level": "pipelayer"}, {"id": "cs-wa-keep", "q": "How long do we have to keep confined space entry permits?", "where": "Spokane, WA", "level": "foreman"}, {"id": "cs-or-sign", "q": "Can the entry supervisor just initial the confined space permit?", "where": "Salem, OR", "level": "foreman"}, {"id": "cs-mi-rule", "q": "Which confined space rule applies to my crew going into a manhole on a Michigan construction job?", "where": "Grand Rapids, MI", "level": "office"}, {"id": "cs-md-rule", "q": "Does Maryland have its own confined space rule for construction?", "where": "Baltimore, MD", "level": "office"}, {"id": "an-oh-life", "q": "How long is my locate ticket good for?", "where": "Cleveland, OH", "level": "office"}, {"id": "an-tx-life", "q": "How long is my 811 ticket good for?", "where": "San Antonio, TX", "level": "office"}, {"id": "an-ga-wait", "q": "How long do I have to wait after calling in my locate tickets before we dig?", "where": "Savannah, GA", "level": "office"}, {"id": "an-mi-zone", "q": "How close to the marks can my crews dig on our tickets?", "where": "Grand Rapids, MI", "level": "office"}, {"id": "an-co-life", "q": "How long are our locate tickets valid?", "where": "Colorado Springs, CO", "level": "office"}]'::jsonb) with ordinality t(e,o)),
g as (select j, (row_number() over (order by n) - 1)/3 b from c)
select '1121-cs-state','ai-next','cs1: 113 confined space state + office 811 cases', 2000+b, array_agg(j->>'id'), jsonb_agg(j) from g group by b;
select pb_ai.eval_pump('1121-cs-state') started, (select count(*) from pb_ai.eval_runs where run = '1121-cs-state') batches, (select sum(cardinality(ids)) from pb_ai.eval_runs where run = '1121-cs-state') n;